import re, sys
from xml.dom import minidom

path = sys.argv[1] if len(sys.argv) > 1 else "unpacked/word/document.xml"
dom = minidom.parse(path)

def get_text(node):
    parts = []
    for r in node.getElementsByTagName("w:t"):
        if r.parentNode is None or r.parentNode.tagName != "w:del":
            parts.append(r.firstChild.nodeValue if r.firstChild else "")
    return "".join(parts)

for i, p in enumerate(dom.getElementsByTagName("w:p")):
    style_el = None
    pPr = p.getElementsByTagName("w:pPr")
    if pPr:
        styles = pPr[0].getElementsByTagName("w:pStyle")
        if styles:
            style_el = styles[0]
    style = style_el.getAttribute("w:val") if style_el is not None else ""
    text = get_text(p)
    print(f"P{i}: style={style!r} text={text!r}")

